try:
    spark.sql(f"OPTIMIZE delta.`{silver_root}` ZORDER BY (City)")
    print("OPTIMIZE ZORDER Silver selesai.")
except Exception as e:
    print("OPTIMIZE ZORDER belum didukung atau gagal.")
    print(str(e)[:1500])

gold_paths = [
    gold_city_path,
    gold_features_path
]

for path in gold_paths:
    try:
        spark.sql(
            f"OPTIMIZE delta.`{path}` ZORDER BY (City)"
        )
        print("Optimasi berhasil:", path)

    except Exception as e:
        print("Optimasi gagal atau tidak didukung:", path)
        print(str(e)[:1000])
